import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import './DealsPage.css';

const DealsPage = () => {
  const { season } = useParams();
  const { t } = useTranslation();
  const [deals, setDeals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Mock data for different seasons
  const mockDeals = {
    winter: [
      { id: 1, title: 'Winter Special 50% Off', store: 'WinterWear', code: 'WINTER50', expiry: '2023-12-31' },
      { id: 2, title: 'Holiday Season Bundle', store: 'GiftShop', code: 'HOLIDAY25', expiry: '2023-12-25' },
      { id: 3, title: 'Snow Gear Clearance', store: 'OutdoorPro', code: 'SNOW30', expiry: '2024-01-15' },
    ],
    summer: [
      { id: 4, title: 'Summer Beach Essentials', store: 'BeachLife', code: 'SUMMER20', expiry: '2023-08-31' },
      { id: 5, title: 'Vacation Package Deals', store: 'TravelPlus', code: 'VACATION15', expiry: '2023-09-15' },
    ],
    spring: [
      { id: 6, title: 'Spring Cleaning Sale', store: 'HomeGoods', code: 'SPRING25', expiry: '2023-04-30' },
      { id: 7, title: 'Garden Supplies Discount', store: 'GardenWorld', code: 'GARDEN10', expiry: '2023-05-15' },
    ],
    fall: [
      { id: 8, title: 'Back to School Specials', store: 'SchoolSupplies', code: 'SCHOOL20', expiry: '2023-09-30' },
      { id: 9, title: 'Fall Fashion Collection', store: 'FashionHub', code: 'FALL15', expiry: '2023-10-31' },
    ],
    // Default deals shown when no season is specified
    default: [
      { id: 10, title: 'Year-round Savings', store: 'AllSeasons', code: 'SAVE10', expiry: '2023-12-31' },
      { id: 11, title: 'New Customer Special', store: 'WelcomeShop', code: 'WELCOME15', expiry: '2023-12-31' },
    ]
  };

  useEffect(() => {
    // Simulate API call
    setLoading(true);
    setTimeout(() => {
      if (season && mockDeals[season.toLowerCase()]) {
        setDeals(mockDeals[season.toLowerCase()]);
      } else if (season) {
        // If season is provided but not found
        setError(`No deals found for ${season} season`);
        setDeals([]);
      } else {
        // Default deals when no season is specified
        setDeals(mockDeals.default);
      }
      setLoading(false);
    }, 800); // Simulate network delay
  }, [season]);

  const formatDate = (dateString) => {
    const options = { year: 'numeric', month: 'long', day: 'numeric' };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  const copyToClipboard = (code) => {
    navigator.clipboard.writeText(code)
      .then(() => {
        alert(`Coupon code ${code} copied to clipboard!`);
      })
      .catch(err => {
        console.error('Failed to copy: ', err);
      });
  };

  if (loading) {
    return (
      <div className="deals-page loading">
        <div className="loading-spinner"></div>
        <p>Loading deals...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="deals-page error">
        <h1>{t('deals.title')}</h1>
        <div className="error-message">
          <p>{error}</p>
          <p>Check out our other seasonal deals:</p>
          <div className="season-links">
            <Link to="/deals/winter">Winter Deals</Link>
            <Link to="/deals/summer">Summer Deals</Link>
            <Link to="/deals/spring">Spring Deals</Link>
            <Link to="/deals/fall">Fall Deals</Link>
            <Link to="/deals">All Deals</Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="deals-page">
      <h1>{season ? `${season.charAt(0).toUpperCase() + season.slice(1)} ${t('deals.title')}` : t('deals.title')}</h1>
      
      {!season && (
        <div className="season-links">
          <Link to="/deals/winter">Winter Deals</Link>
          <Link to="/deals/summer">Summer Deals</Link>
          <Link to="/deals/spring">Spring Deals</Link>
          <Link to="/deals/fall">Fall Deals</Link>
        </div>
      )}
      
      {deals.length > 0 ? (
        <div className="deals-container">
          {deals.map(deal => (
            <div className="deal-card" key={deal.id}>
              <h3>{deal.title}</h3>
              <p className="store-name">{deal.store}</p>
              <div className="coupon-code">
                <span>{deal.code}</span>
                <button onClick={() => copyToClipboard(deal.code)}>Copy</button>
              </div>
              <p className="expiry">Expires: {formatDate(deal.expiry)}</p>
            </div>
          ))}
        </div>
      ) : (
        <p className="no-deals">No deals available at this time. Please check back later.</p>
      )}
      
      {season && (
        <div className="back-link">
          <Link to="/deals">View All Deals</Link>
        </div>
      )}
    </div>
  );
};

export default DealsPage;
